'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
    while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
    let num = 0;
    while (pos < input.length) {
        const code = input.charCodeAt(pos);
        if (code < 48 || code > 57) break;
        num = num * 10 + code - 48;
        pos++;
    }
    return num;
}

const n = nextInt();
const m = nextInt();

const type = new Uint8Array(n);
for (let i = 0; i < n; i++) type[i] = nextInt();

const headOut = new Int32Array(n);
const headIn = new Int32Array(n);
headOut.fill(-1);
headIn.fill(-1);

const to = new Int32Array(m);
const from = new Int32Array(m);
const nextOut = new Int32Array(m);
const nextIn = new Int32Array(m);

for (let i = 0; i < m; i++) {
    const a = nextInt() - 1;
    const b = nextInt() - 1;

    from[i] = a;
    to[i] = b;

    nextOut[i] = headOut[a];
    headOut[a] = i;

    nextIn[i] = headIn[b];
    headIn[b] = i;
}

const forward = new Uint8Array(n);
const backward = new Uint8Array(n);
const queue = new Int32Array(n);

let left = 0;
let right = 0;

for (let i = 0; i < n; i++) {
    if (type[i] === 1) {
        forward[i] = 1;
        queue[right++] = i;
    }
}

while (left < right) {
    const v = queue[left++];

    for (let e = headOut[v]; e !== -1; e = nextOut[e]) {
        const u = to[e];
        if (type[u] !== 1 && forward[u] === 0) {
            forward[u] = 1;
            queue[right++] = u;
        }
    }
}

left = 0;
right = 0;

for (let i = 0; i < n; i++) {
    if (type[i] === 2) {
        backward[i] = 1;
        queue[right++] = i;
    }
}

while (left < right) {
    const v = queue[left++];

    if (type[v] === 1) continue;

    for (let e = headIn[v]; e !== -1; e = nextIn[e]) {
        const u = from[e];
        if (backward[u] === 0) {
            backward[u] = 1;
            queue[right++] = u;
        }
    }
}

const answer = new Array(n);
for (let i = 0; i < n; i++) {
    answer[i] = forward[i] && backward[i] ? '1' : '0';
}

process.stdout.write(answer.join('\n'));

